const {Playtest,SLOTS,COST,project}=BonePick;
const $=id=>document.getElementById(id),c=$('field').getContext('2d');let g=new Playtest(),mode=null,clock=0,last=0,uiAt=0;
function oval(x,y,rx,ry,fill,stroke=null,w=2){c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=w;c.stroke();}}
function line(x,y,X,Y,color,width=3){c.beginPath();c.moveTo(x,y);c.lineTo(X,Y);c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.stroke();}
function poly(points,color,stroke=null,w=2){c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.fillStyle=color;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=w;c.stroke();}}
function leaf(x,y,s=1,a=0){c.save();c.translate(x,y);c.rotate(a);oval(0,0,7*s,14*s,'#83a955','#55723c',1);line(0,-10*s,0,11*s,'#52733c',s);c.restore();}
function skeleton(e){const p=project(e.lane,e.d);if(e.fall){const prev=project(e.fromLane,e.fromD);p.y+=(prev.y-p.y)*e.fall/.65;}const s=p.scale*(e.brute?1.35:1),walk=(e.held||e.stun)?0:Math.sin(clock*8)*3;c.save();c.translate(p.x,p.y);c.scale(s,s);oval(0,1,21,7,'#384e2a30');const bone=e.flash?'#fff7d7':'#e6dfc0',edge='#66694d';line(-7,-29,-11,-3+walk,edge,8);line(-7,-29,-11,-3+walk,bone,5);line(7,-29,12,-3-walk,edge,8);line(7,-29,12,-3-walk,bone,5);oval(-13,-2+walk,7,3,bone,edge,1);oval(14,-2-walk,7,3,bone,edge,1);line(0,-54,0,-25,edge,6);line(0,-54,0,-25,bone,3);for(let j=0;j<3;j++){c.beginPath();c.ellipse(0,-49+j*7,11-j,4,0,0,Math.PI);c.strokeStyle=edge;c.lineWidth=5;c.stroke();c.strokeStyle=bone;c.lineWidth=3;c.stroke();}line(-10,-52,-23,-32+walk,edge,6);line(-10,-52,-23,-32+walk,bone,3);line(10,-52,23,-33-walk,edge,6);line(10,-52,23,-33-walk,bone,3);oval(0,-70,19,18,bone,edge,2);poly([[-11,-62],[-10,-53],[10,-53],[12,-62]],bone,edge,1.5);oval(-7,-71,5,6,'#45513e');oval(8,-71,5,6,'#45513e');poly([[0,-65],[-3,-61],[3,-61]],'#677056');for(let x=-6;x<=6;x+=6)line(x,-58,x,-53,'#858967',1);if(e.brute){line(-22,-45,22,-45,'#ddd3ac',7);line(-22,-38,22,-38,'#ddd3ac',7);poly([[-18,-81],[-19,-94],[-7,-88],[1,-100],[9,-88],[19,-94],[19,-81]],'#c4a259',edge,2);c.fillStyle='#ae6c42';c.fillRect(-16,-110,32,4);c.fillStyle='#f2cd6d';c.fillRect(-16,-110,16*e.hp,4);}if(e.held>0){for(let k=0;k<3;k++){c.beginPath();c.ellipse(0,-5-k*5,19-k*2,6,0,0,Math.PI*2);c.strokeStyle='#577a3a';c.lineWidth=4;c.stroke();}leaf(14,-10,.55,.8);}c.restore();}
function chipmunk(lane,d,load=0){const p=project(lane,d),s=p.scale*.85;c.save();c.translate(p.x+57*p.scale,p.y);c.scale(s,s);oval(18,-15,12,22,'#a76e3d','#5e4f30',2);oval(19,-18,6,17,'#d5ad73');oval(0,-13,15,20,'#b68048','#5e4f30',2);oval(-4,-12,9,16,'#e4c085');line(3,-28,5,-4,'#473f2d',5);line(7,-26,9,-6,'#f2d6a1',3);oval(-9,-43,7,8,'#aa7741');oval(8,-43,7,8,'#aa7741');oval(-2,-33,19,17,'#bd8951','#5e4f30',2);oval(-10,-28,9,8,'#e4bb7e');oval(8,-28,8,8,'#e4bb7e');oval(-7,-36,3,4,'#303c2b');oval(7,-36,3,4,'#303c2b');oval(0,-29,4,3,'#5a432e');line(0,-25,5,-23,'#5a432e',1.5);oval(-9,3,8,4,'#80552e');oval(9,3,8,4,'#80552e');poly([[-14,-20],[12,-20],[12,-14],[-14,-14]],'#5d8143');if(load){poly([[-23,-12],[13,-12],[9,5],[-19,5]],'#96a15c','#526f36',2);line(-18,-14,5,-17,'#eee4bd',5);oval(-4,-20,7,6,'#eee4bd');}c.restore();}
const names={snare:'Root Snare',log:'Log Drop',branch:'Brambles'},lanes=['Crown','Bough','Home'];
function background(){
 const sky=c.createLinearGradient(0,0,0,720);sky.addColorStop(0,'#a4beb0');sky.addColorStop(1,'#d1d7ae');c.fillStyle=sky;c.fillRect(0,0,600,720);
 for(let i=0;i<9;i++){const x=i*81-20;line(x,720,x,0,'#688b7933',28);oval(x,80,80,120,'#79958033');}
 poly([[180,0],[420,0],[398,180],[415,400],[455,720],[145,720],[185,400],[202,180]],'#87613e','#62472f',4);
 for(let i=0;i<9;i++)line(205+i*23,0,175+i*31,720,i%2?'#9a744c':'#735135',3);
 // Warm windows and a small protected home at the end of the bottom route.
 for(let l=0;l<2;l++){oval(300,100+l*205,22,34,'#e8ba65','#5c422d',5);line(300,69+l*205,300,130+l*205,'#735332',4);line(279,102+l*205,320,102+l*205,'#735332',4);}
 for(let l=0;l<3;l++){let y=205+205*l;poly([[0,y],[600,y],[600,y+19],[490,y+23],[330,y+18],[130,y+28],[0,y+20]],'#88603c','#59462d',3);line(0,y,600,y,'#a4a16a',8);for(let i=0;i<18;i++)leaf(i*35,y+10,.35,i*.7);
 c.font='bold 14px system-ui';c.fillStyle='#fff2c6';c.textAlign='left';c.fillText(lanes[l].toUpperCase()+(l===1?'  ←':'  →'),12,y+48);
 if(l<2){const x=l===0?554:45;line(x-12,y+25,x-12,y+175,'#584b32',5);line(x+12,y+25,x+12,y+175,'#584b32',5);for(let k=0;k<7;k++)line(x-12,y+30+k*23,x+12,y+30+k*23,'#c29a60',5);}}
 poly([[510,615],[510,550],[535,526],[560,550],[560,615]],'#e6b966','#59422a',4);line(534,553,534,613,'#97723f',2);oval(548,585,3,3,'#6e512d');
}
function trap(t){const p=project(t.lane,t.d);c.save();c.translate(p.x,p.y);const ready=t.cooldown<=0;
 if(t.type==='snare'){for(let j=0;j<3;j++){c.beginPath();c.ellipse(0,-5-j*6,25-j*3,9,0,0,7);c.strokeStyle=ready?'#557b3f':'#8a885c';c.lineWidth=5;c.stroke();}leaf(23,-15,.6,.8);}
 if(t.type==='branch'){poly([[-34,0],[-26,-27],[-16,-10],[-6,-33],[5,-12],[20,-30],[33,0]],ready?'#547445':'#81815b','#374e32',3);for(let i=0;i<5;i++)line(-24+i*12,-6,-30+i*12,-20,'#a47449',3);}
 if(t.type==='log'){c.fillStyle='#493b2c';c.fillRect(-30,-4,60,11);line(-36,0,-36,-120,'#61482e',6);line(36,0,36,-120,'#61482e',6);line(-36,-120,36,-120,'#61482e',7);const y=t.swing>0?-20:-83;line(-20,-120,-20,y,'#cfb47a',3);line(20,-120,20,y,'#cfb47a',3);c.fillStyle='#a67b49';c.fillRect(-31,y-13,62,26);oval(-31,y,9,13,'#cba064','#5a412c',3);oval(31,y,9,13,'#bd9057','#5a412c',3);line(-20,y-8,21,y-8,'#d2aa6d',2);}
 c.textAlign='center';c.font='bold 10px system-ui';c.fillStyle=ready?'#fff1ba':'#ecdcae';c.fillText(ready?'ARMED':Math.ceil(t.cooldown)+'s',0,24);c.restore();}
function render(){background();for(const t of g.traps)trap(t);
 if(mode&&mode!=='remove')for(let l=0;l<3;l++)for(let slot=0;slot<4;slot++){if(mode==='log'&&l===2||g.traps.some(t=>t.lane===l&&t.slot===slot))continue;const p=project(l,SLOTS[slot]);oval(p.x,p.y-7,24,11,'#f6db7844','#f6df9c',2);}
 for(const p of g.piles){const q=project(p.lane,p.d);line(q.x-13,q.y-5,q.x+13,q.y-18,'#efe6c6',6);line(q.x-13,q.y-18,q.x+13,q.y-5,'#efe6c6',6);oval(q.x,q.y-21,9,8,'#f4e7c5','#6d6650',1);}
 for(const e of g.enemies)skeleton(e);
 if(g.crew.state!=='home')chipmunk(g.crew.lane,g.crew.d,g.crew.load);else chipmunk(2,.2,0);
 for(const fx of g.effects){const p=project(fx.lane,fx.d);c.fillStyle='#fff0be';c.font='bold 21px Georgia';c.textAlign='center';c.fillText('CRACK!',p.x,p.y-65-(.7-fx.life)*30);}}
function say(t){$('message').textContent=t;}
function select(t){mode=mode===t?null:t;update();}
function target(label,p,handler,kind){const b=document.createElement('button');b.className='target '+kind;b.setAttribute('aria-label',label);b.title=label;b.style.left=p.x/6+'%';b.style.top=(p.y-16)/7.2+'%';b.textContent=kind==='slot'?'+':kind==='pile'?'↟':'×';b.onclick=handler;$('targets').append(b);}
function update(){
 $('health').textContent=g.oak+'%';$('materials').textContent=g.materials;$('timer').textContent=g.phase==='prep'?'Prepare':g.time>=60?'Clear up':Math.ceil(60-g.time)+'s';$('start').hidden=g.phase!=='prep';$('pause').disabled=!['playing','paused'].includes(g.phase);$('pause').textContent=g.phase==='paused'?'Resume':'Pause';$('paused').hidden=g.phase!=='paused';
 for(const t of ['snare','log','branch'])$(t).classList.toggle('selected',mode===t);$('remove').textContent=mode==='remove'?'Cancel removal':'Remove trap';$('hint').textContent=mode==='log'?'Place above brambles for a falling combo.':mode==='remove'?'Tap a trap to reclaim materials.':mode?'Tap a glowing planting spot.':'Choose a trap. Everything triggers automatically.';
 $('crew').textContent=g.crew.state==='home'?'Chipmunk ready · tap bones to salvage':g.crew.state==='flee'?'Retreating!':g.crew.load?'Bringing '+g.crew.load+' materials home':'Crew collecting bones…';$('recall').disabled=g.crew.state==='home'||g.phase!=='playing';
 $('targets').replaceChildren();if(['prep','playing'].includes(g.phase)){
 if(mode&&mode!=='remove')for(let l=0;l<3;l++)for(let slot=0;slot<4;slot++){if(mode==='log'&&l===2||g.traps.some(t=>t.lane===l&&t.slot===slot))continue;target(`Build ${names[mode]}: ${lanes[l]}, position ${slot+1}`,project(l,SLOTS[slot]),()=>{const err=g.place(mode,l,slot);if(err)say(err);update();},'slot');}
 if(mode==='remove')for(const t of g.traps)target('Remove '+names[t.type],project(t.lane,t.d),()=>{g.remove(t.id);update();},'remove');
 for(const p of g.piles)target('Salvage bones on '+lanes[p.lane],project(p.lane,p.d),()=>{const err=g.send(p.id);if(err)say(err);update();},'pile');}
}
function reset(){g=new Playtest();mode=null;$('result').hidden=true;$('intro').hidden=true;say('A Log Drop and brambles are ready. Build your backup defenses.');update();}
$('begin').onclick=()=>{$('intro').hidden=true;update();};for(const t of ['snare','log','branch'])$(t).onclick=()=>select(t);$('remove').onclick=()=>select('remove');$('start').onclick=()=>{mode=null;g.start();update();};$('pause').onclick=()=>{g.phase=g.phase==='paused'?'playing':'paused';update();};$('restart').onclick=reset;$('again').onclick=reset;$('recall').onclick=()=>{g.recall();update();};
let helpPhase=null;$('help').onclick=()=>{helpPhase=g.phase;if(g.phase==='playing')g.phase='paused';$('helpPanel').hidden=false;update();};$('closeHelp').onclick=()=>{$('helpPanel').hidden=true;if(helpPhase==='playing')g.phase='playing';update();};document.addEventListener('visibilitychange',()=>{if(document.hidden&&g.phase==='playing'){g.phase='paused';update();}});
function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;clock+=dt;g.step(dt);while(g.events.length){const e=g.events.shift();say(e.text);if(e.type==='won'||e.type==='lost'){$('result').hidden=false;$('resultTitle').textContent=e.type==='won'?'Home, sweet Oak.':'The siege got through.';$('resultText').textContent=`${g.stats.kills} skeletons busted · ${g.stats.drops} drops · ${g.stats.recovered} materials recovered. Try stacking Log Drops directly above brambles.`;}}render();if(clock-uiAt>.15){update();uiAt=clock;}requestAnimationFrame(frame);}update();requestAnimationFrame(frame);
